use vstd::prelude::*;
use vstd::vec::*;

verus! {

/// Predicate: n is an even number
spec fn is_even_int(n: int) -> bool {
    n % 2 == 0
}

/// Predicate: index i is even (for usize/ints)
spec fn is_even_index(i: int) -> bool {
    i % 2 == 0
}

/// Specification: all elements at even indices in the vector are even
spec fn all_even_indices_even(vec: Vec<i32>) -> bool {
    forall|i: int| 0 <= i < vec.len() && is_even_index(i) ==> is_even_int(vec[i])
}

fn is_even_at_index_even(lst: &Vec<i32>) -> (result: bool)
    ensures
        result == all_even_indices_even(lst@),
{
    let mut i: usize = 0;
    
    while i < lst.len()
        invariant
            // i is even and within bounds
            i % 2 == 0,
            i <= lst.len(),
            // All even indices less than i have even values
            forall|j: int| 0 <= j < i && is_even_index(j) ==> is_even_int(lst[j]),
        decreases
            (lst.len() - i) / 2,
    {
        // Check if the element at even index is even
        if lst[i] % 2 != 0 {
            // Found an odd element at even index
            assert(!all_even_indices_even(lst@));
            return false;
        }
        
        // Move to next even index
        if i + 2 > i {  // Check for overflow
            i += 2;
        } else {
            // If overflow would occur, break (i is already at or near max usize)
            break;
        }
    }
    
    // All even-indexed elements are even (or there are none)
    assert(all_even_indices_even(lst@));
    true
}

}